quests[40470] = { id = 40470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quality of Life", description = "I am afraid, {name}. We're so close to home, so close to salvation...\n\nAstoril says he knows the rest of the way through and can get us there safely. I believe him, but you've come this far to see us safe. Will you see this through to the end?", completion = "This is a most troubling tale. \n\nYou have done a good thing, {name}. Now he will no longer torment our people.", objectives = "Follow Iadreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
