quests[40495] = { id = 40495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ulthalesh, the Deadwind Harvester", description = "The book says the Dark Riders were last seen in a place called Manor Mistmantle. If friend can find these riders, then <he/she> can get Ulthalesh!\n\nCalydus will wait here and await your return. Find Ulthalesh, friend!", progress = "And just why should I help you, {class}?", completion = "I am left with little choice. I cannot face another Dark Rider ambush alone, and you are obviously formidable.\n\nI will help you find the weapon you seek, but only if you will allow me to return the others in their possession to their rightful place.\n\nDo we have a deal, {class}?", objectives = "Start your search for the Deadwind Harvester at Manor Mistmantle in Duskwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
