quests[40501] = { id = 40501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSEME_40501", description = "If Garona's intelligence is correct, Gul'dan will be inside this Iron Horde compound. With Garona's help, slip inside, gather any info you find, and learn what Gul'dan intends to do.\n\nThe guards are on high alert. Garona can \"liquidate\" individual guards for you, but she must not be seen! You will have to choose your targets carefully and pick your way through the bastion undetected. Don't let anyone sound the alarm.\n\nIf things get too hot, I'll teleport you to safety. At least... I'll try.", objectives = "Infiltrate Bladefury's Command with Garona's help. Use her talents to eliminate guards without being seen. Locate Iron Horde intelligence and then spy on Gul'dan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
