quests[40514] = { id = 40514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revil Convinced" }
quests[40515] = { id = 40515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Walk With the Spirits", description = "The spiritwalker you saved from Riverbend has been insufferable since his arrival. He is insisting on showing you the ways of our people so that you better understand what is to come.\n\nHe is a strange one, even by spiritwalker standards.\n\nEven so, only a fool would discard his insight. Please, go to speak with him when you get a moment.", completion = "You made Mayla smile. That is the first time I have seen her smile in... ever?", objectives = "Speak with Spiritwalker Ebonhorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40516] = { id = 40516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dawning Bit" }
quests[40517] = { id = 40517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fallen Lion", description = "I haven't left the deck of this ship since we got back. The fleet must be made ready for war. Don't know where we will be needed, but when the call comes, we'll be ready.\n\nTruth be told... I welcome the distraction. The others are paying their respects to Varian, but I... I cannot bring myself to face that casket. To face his son.\n\nVarian gave me a letter he wrote to Anduin. Please, take it to him on my behalf.", progress = "Welcome, {name}. I am pleased you survived the battle. You have something for me?", completion = "<Anduin sighs and reads the letter from his father. Tears well in his eyes. He is silent for several moments.>\n\nThank you for bringing this to me, {name}, it means... more than I can say. I wish Greymane felt he could present it himself, but his mind is fixed on revenge.\n\nI cannot blame him... or Jaina, for that matter, but we must find a better way.\n\nEnough of such talk. It is good you are here. We will need heroes like you in the many battles to come.", objectives = "Deliver King Varian's letter to King Anduin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40518] = { id = 40518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Broken Shore", description = "Your warship awaits at the end of the dock, {name}. May your weapon bring you many kills today.\n\nThe Warchief has already made landfall, I will wager you will simply need to follow the trail of demon blood.", completion = "Glad to see you back on your feet, {name}. Many good soldiers who sailed for the Broken Shore were not so fortunate.", objectives = "Take Captain Russo's ship to the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40519] = { id = 40519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion: The Legion Returns", description = "Heroes of the Alliance, I write to you in Azeroth's darkest hour. From the maw of hell, the burning armies of the Legion have returned.\n\nOur fleets depart for the Broken Isles at once. As a grand lance, we will pierce the Legion's lines and drive them back to the nether that spawned them.\n\nYour ship awaits in the Stormwind Harbor, make haste.", completion = "Hail, {name}. I've got your ship assignment right here.\n\nBut first, a bit of readiness is in order!", objectives = "Check in with Recruiter Lee at Stormwind Harbor.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40520] = { id = 40520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To See the Past", description = "I would like for you to experience firsthand what Huln Highmountain was able to accomplish in a single battle during the War of the Ancients.\n\nTo do so, I will need very specific ingredients. They are not too difficult to obtain--you can find all of them near Thunder Totem.", progress = "Earth, air, and water are all magics we have come to know well in our mountain.", completion = "Ah, these will be perfect for what is in store.", objectives = "Collect a Bottle of Airspark, Mu'sha's Tears, and Darkshard Crystal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40521] = { id = 40521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - W1 - Demon Attack Complete" }
quests[40522] = { id = 40522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate of the Horde", description = "It is a wonder any of our troops survived that bloodbath on the Broken Shore. If not for Lady Sylvanas...\n\nHigh Overlord Saurfang has been asking for you at Grommash Hold. He will not say why... but he was insistent that I send you to him.", progress = "Dark days are upon us.", completion = "You have served the Horde well in the past, {name}.\n\nMore will be asked of you... much more.", objectives = "Go to Grommash Hold and learn the fate of the Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40523] = { id = 40523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Facet-nating Friends", description = "Excuse me, <sir/madam>. Are you sure you're in the correct shop? We only deal in the finest of jewels here.\n\nAhh, I see... you're a fellow lapidary. Then perhaps we can work together.\n\nIntroduce yourself to my associates, so they're aware of who you are and what you may have to offer.", progress = "Get yourself acquainted and we'll discuss business.", completion = "As for myself, I'm the proprietor of this establishment. If you have any questions concerning our shop, please direct them to me.\n\nNow, onto business.", objectives = "Introduce yourself to Timothy Jones and Sminx Glasseye.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40524] = { id = 40524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Familiar Ring to It", description = "{name}! Let's talk bling. I'm looking for a ring.\n\nSee, the elves down in Azsuna were some fine master jewelcrafters back in the day... or so they say. The books all talk about a ring called the \"Band of Farondis\". Can't hurt to ask around for it.\n\nLet's head to Azsuna. Bet I'll get there sooner!", progress = "Have you tracked down the ring?", completion = "So the ring was stolen by murlocs? Sounds like another opportunity for you and I to work together!\n\nPartners in crime, for the rest of time!", objectives = "Find the Shrine of Aldiir near the Crumbling Palace in Azsuna and read about its legend.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40525] = { id = 40525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting the Band Back Together", description = "I like our dynamic, {name}. You're the muscle with all the hustle! And I'm the brains who entertains!\n\nI think this next task is all on you. Try to find that ring, or whatever the murlocs left of it.", progress = "How goes the hunt for the ring?", completion = "You got all the pieces!\n\n<Timothy looks over each piece and nods his head.>\n\nYeah, I can fix this. No prob, bob.", objectives = "Find the three pieces of the Band of Farondis and bring them back to Timothy Jones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40526] = { id = 40526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finishing Touches", description = "Well, I've managed to repair the ring, but the gem still needs work.\n\nSay... you're a gemcutter, {name}. You've got the tools, so cut those jewels!", progress = "How'd you do?", completion = "Oh yes! That is a choice-lookin' skystone.\n\n<Timothy pops the stone into the fixed ring.>\n\nLike a painter or poet, I'm a master'n you know it!\n\nTell ya what, since you did all the legwork, I'll share the design for this ring with you.", objectives = "Use Timothy's Gem Vise to obtain a Cut Skystone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40527] = { id = 40527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finishing Touches", description = "Well, I've managed to repair the ring, but the gem still needs work.\n\nSay... you're a gemcutter, {name}. You've got the tools, so cut those jewels!", progress = "How'd you do?", completion = "Oh yes! That is a choice-lookin' deep amber.\n\n<Timothy pops the stone into the fixed ring.>\n\nLike a painter or poet, I'm a master'n you know it!\n\nTell ya what, since you did all the legwork, I'll share the design for this ring with you.", objectives = "Use Timothy's Gem Vise to obtain a Cut Deep Amber.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40528] = { id = 40528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finishing Touches", description = "Well, I've managed to repair the ring, but the gem still needs work.\n\nSay... you're a gemcutter, {name}. You've got the tools, so cut those jewels!", progress = "How'd you do?", completion = "Oh yes! That is a choice-lookin' azsunite.\n\n<Timothy pops the stone into the fixed ring.>\n\nLike a painter or poet, I'm a master'n you know it!\n\nTell ya what, since you did all the legwork, I'll share the design for this ring with you.", objectives = "Use Timothy's Gem Vise to obtain a Cut Azsunite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40529] = { id = 40529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truly Outrageous", description = "Ore prospecting is our primary method of gem acquisition. And while prospecting... you're bound to find small, unusable gem chips.\n\nMany gem shops simply discard the small gem chips they find, but we here at Cartier & Co. let nothing go to waste.", progress = "Try not to get any blood on them while you're out \"adventuring\".", completion = "<Tiffany looks over the gem chips.>\n\nYes, I suppose these will do.\n\nQuite different from the ones I'm used to working with, but then again, we're not exactly in Northrend anymore.\n\nHere's a design for one of the newer jewels with which I've been working. I call it a Versatile Skystone.", objectives = "Gather 5 Gem Chips for Tiffany Cartier. Gem Chips can be acquired through Prospecting raw ore or purchased off the auction house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40530] = { id = 40530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Eye for Detail", description = "{name}, if there's one thing I despise, it's slander. A rumor is spreading that one of my recent commissions is a fake.\n\nWe need to quell these rumors as quickly as possible.\n\nI need you to visit the customers I recently worked for and examine their gems. If your claim of being a jewelcrafter is true, then you will be able to spot a fake gem from a mile away.\n\nHere's the list of my patrons. Return immediately if you find any truth to these rumors.", progress = "I will not let these falsehoods ruin the good name of Tiffany & Co.", completion = "What's this?\n\n<Tiffany opens the bag and pulls out a jewel. She examines it and then drops it on the floor, where it shatters.>\n\nThese jewels were delivered by...\n\nWINSTON!!! That thief! How dare he switch them out for these... pathetic imitations!", objectives = "Visit the patrons of the jewelcrafting shop in Dalaran and report back to Tiffany.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40531] = { id = 40531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swift Vengeance", description = "I swear, when I find him...\n\n<Tiffany catches your eye and regains her composure.>\n\n{name}, I need you to track down my FORMER associate, Harold Winston. I doubt he's gotten far, given our location.\n\nWhen you find him, I would like you to recover the stolen property and return it to me.\n\nUse any means necessary. And don't worry about Ms. Moore's jewels, I'll redeliver a fresh supply to her personally.", progress = "Did you find him? Were you able to recover the jewels?", completion = "<Tiffany takes the bag from you and pulls out the jewels. She carefully looks over each one.>\n\nGood, they're all here. And from the looks of it, they're all the original jewels.\n\nHow did you deal with... actually, nevermind. I really don't care.", objectives = "Find Harold Winston in Dalaran's Underbelly.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40532] = { id = 40532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making the Cut", description = "Seeing as how you've been quite a reliable resource, I'm willing to teach you how to cut a Deadly Deep Amber.\n\nWe'll be using my cutting tool to do this, so whenever you're ready, go ahead and sit yourself in front of it.", progress = "Make sure not to break the raw gem. We don't just have a stockpile of those lying around.", completion = "<Tiffany examines your work.>\n\nI see. I would have ground this facet's angle differently... but your work is passable.\n\nWhy don't I write down my design for you. That way, you can try to be more like me.", objectives = "Craft a Deadly Deep Amber using the Tiffany's cutting tool.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40533] = { id = 40533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making the Cut", description = "Seeing as how you've been quite a reliable resource, I'm willing to teach you how to cut a Quick Azsunite.\n\nWe'll be using my cutting tool to do this, so whenever you're ready, go ahead and sit yourself in front of it.", progress = "Make sure not to break the raw gem. We don't just have a stockpile of those lying around.", completion = "<Tiffany examines your work.>\n\nI see. I would have ground this facet's angle differently... but your work is passable.\n\nWhy don't I write down my design for you. That way, you can try to be more like me.", objectives = "Craft a Quick Azsunite using the Tiffany's cutting tool.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40534] = { id = 40534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making the Cut", description = "Seeing as how you've been quite a reliable resource, I'm willing to teach you how to cut a Masterful Queen's Opal.\n\nWe'll be using my cutting tool to do this, so whenever you're ready, go ahead and sit yourself in front of it.", progress = "Make sure not to break the raw gem. We don't just have a stockpile of those lying around.", completion = "<Tiffany examines your work.>\n\nI see. I would have ground this facet's angle differently... but your work is passable.\n\nWhy don't I write down my design for you. That way, you can try to be more like me.", objectives = "Craft a Masterful Queen's Opal using the Tiffany's cutting tool.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40535] = { id = 40535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raising the Drogbar", description = "Word travels fast around Dalaran, {name}. And the latest word is that there's a master jewelcrafter somewhere in Val'sharah.\n\nI want you to go down there and find this master.  Perhaps they have designs that can help bolster business here at the shop.\n\nI've heard the name \"Lasune Starblade\" tied to these rumors. She might be a good place to start looking.", progress = "Those damned harpies ambushed Jabrul!", completion = "Jabrul thanks you, {name}.", objectives = "Talk to Lasune Starblade in Val'sharah as to the whereabouts of the jewelcrafting master.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40536] = { id = 40536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruls Before Jewels", description = "So, you wish to learn what Jabrul knows about jewels?\n\nWell, Jabrul needs your help. Before we leave this place, Jabrul still needs harpy necklaces.\n\nKeep those harpies off of Jabrul while he takes their necklaces and Jabrul will reward you with his knowledge.", completion = "It feels good to be out of there. As promised, Jabrul will share with you some of his knowledge.\n\nWhat is it you're most interested in learning about?", objectives = "Protect Jabrul while he finds harpy necklaces and escort him back to the nearby night elf camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40537] = { id = 40537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drawing Blood", description = "Hey, {name}! I have something exciting to tell you about, but you must keep a secret. Just between us scribes.\n\n<Zooey gives you a wink and pulls out a large tome.>\n\nThis is the Bloodbound Ledger. Inscribing your name in it allows you to learn how to craft \"blood contracts\" which can hurt a little bit, but are absolutely worth it!\n\nI currently know one of them and I get so excited when I use it 'cause it... well, you'll see.\n\nSo whaddya say? Interested?", completion = "Let's see here. Yes, everything looks in order and it appears the spell has already taken effect on you.\n\nYou're now able to learn how to craft the deadly, eerily haunting, \"blood contracts\". WoooOOOooo.\n\n<Zooey puts on some theatrics as she says the last part.>\n\nHaha, just messin' with ya, {name}. But seriously, these things can be pretty dangerous.", objectives = "Sign the Bloodbound Ledger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40538] = { id = 40538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lapidary Lessons", description = "It's good to see you again, {name}.\n\nIt seems we've both been busy since last we spoke. I have something that you may be interested in.\n\nA recent shipment of rare jewels called maelstrom sapphires have finally arrived here at the shop.\n\nI came up with a beautiful design for them and would like to show you how to cut them into something useful.", progress = "I'd recommend keeping a steadier hand than usual with these jewels.", completion = "<Tiffany looks over the gem and nods her head.>\n\nVery good work, {name}. It seems your skills have improved since the last time you cut something for me.\n\nEnjoy that design, it's one of my finest.", objectives = "Craft a Well-Cut Maelstrom Sapphire using Tiffany's cutting tool.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40539] = { id = 40539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Intentions", description = "Word on the street is, yer a reliable resource for getting things done, let's say, discreetly.\n\nSo here's the job. I need a new set of lock picking tools. But not just any old lock picks will do.\n\nI need something special, something that won't break if ye apply too much pressure.\n\nI'm thinking a set of diamond lock picks might do the trick. That would be lock picks made out of diamond, not the ones shaped like a diamond.\n\nLook, ye in or what?", progress = "Try not to attract too much attention, okay?", completion = "<Clive looks over the lock picks.>\n\nNot bad, not bad.\n\nListen, me friend, you've done me a great service today. I trust now that you have the design, should I ever need another set, I'll know who to contact.\n\n<Clive gives you a sly wink of his eye.>", objectives = "Collect a set of Diamond Lockpicks for Clive Cozen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40540] = { id = 40540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Come at Me, Brul", description = "{name}, I received a... well, what can only be constituted as a \"letter\", carved into a piece of flat rock.\n\nThat jewelcrafting master you found in Val'sharah has sent for you. He said he's in Stormheim currently.\n\nWhen you see him, would you be so kind as to inform him that we don't wish to receive any more of his requests for your presence. They just make a mess.", completion = "Good to see you again, {name}. Jabrul wanted to know if you would like to learn some more designs.", objectives = "Find Jabrul in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40541] = { id = 40541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Charge Within", description = "Before Jabrul shares his designs with you, he needs you to help him with a special project.\n\nJabrul has a jewel that can trap storm energy. The more lightning it traps, the brighter it shines.\n\nJabrul thinks the storm drakes' power would be better spent in his jewel than terrorizing the skies of Stormheim.\n\nDon't you?", completion = "Jabrul has never seen something so radiant in all his life.", objectives = "Use the Conducting Jewel on the corpses of 10 Squallhunter storm drakes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40542] = { id = 40542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of Nashal", description = "Deadly eye of prophecy... a good choice. Before we can cut, though, we need gems.\n\nHere stands a giant statue of Nashal, an ancient vrykul. Laid in its eye sockets are two of the stones we need.\n\nAscend the statue, take its jeweled eyes, and return them to Jabrul.", progress = "Jabrul is anxious to see these jewels up close.", completion = "I hope these weren't too heavy for a small brul such as yourself to carry.\n\nBut these will be more than enough to show you a suitable design.\n\n<Jabrul begins to carve one of the jewels into a design, instructing you how it's done as he works.>", objectives = "Obtain 2 Eyes of Nashal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40543] = { id = 40543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of Nashal", description = "Quick dawnlight... a good choice. Before we can cut, though, we need gems.\n\nHere stands a giant statue of Nashal, an ancient vrykul. Laid in its eye sockets are two of the stones we need.\n\nAscend the statue, take its jeweled eyes, and return them to Jabrul.", progress = "Jabrul is anxious to see these jewels up close.", completion = "I hope these weren't too heavy for a small brul such as yourself to carry.\n\nBut these will be more than enough to show you a suitable design.\n\n<Jabrul begins to carve one of the jewels into a design, instructing you how it's done as he works.>", objectives = "Obtain 2 Eyes of Nashal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40544] = { id = 40544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of Nashal", description = "Masterful shadowruby... a good choice. Before we can cut, though, we need gems.\n\nHere stands a giant statue of Nashal, an ancient vrykul. Laid in its eye sockets are two of the stones we need.\n\nAscend the statue, take its jeweled eyes, and return them to Jabrul.", progress = "Jabrul is anxious to see these jewels up close.", completion = "I hope these weren't too heavy for a small brul such as yourself to carry.\n\nBut these will be more than enough to show you a suitable design.\n\n<Jabrul begins to carve one of the jewels into a design, instructing you how it's done as he works.>", objectives = "Obtain 2 Eyes of Nashal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40545] = { id = 40545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aww Scrap!", description = "It's a catastrophe! No, even worse, a conspiracy!\n\nI heard the Legion was back again, and I thought to myself, \"Hobart, now's your time to shine.\"\n\nI made us enough guns to blow those demons back to the beginning of time!\n\nBut then we get here, and what happens? Everyone just happens to \"find\" all these ancient artifacts to fight the demons with!\n\nLong story short, I have too many guns and need to get rid of 'em.", completion = "Now that's quite the haul of guns! I suppose these fell off the back of a gryphon, right?\n\n<Filgo gives you a sly wink.>", objectives = "Take the Crate of Guns down to Filgo Scrapbottom in the Underbelly.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40546] = { id = 40546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysteries of Nature", description = "Jabrul wants to show you his special crystals. Nobody knows what they do. Very mysterious.\n\nIf you want to learn how to make one, Jabrul would be happy to show you.\n\nHigh in the mountains live storm drakes. They blast the cliffs with their lightning breath and sometimes blast so hard, they turn the rock to crystal.\n\nGet a piece of that crystal and bring it back to Jabrul.", progress = "Got the stone?", completion = "An excellent piece. Now watch carefully...\n\n<Jabrul begins to carve the glass into a rather interesting shape, describing how the shape of the gem dictates its behavior.>", objectives = "Recover a piece of Dragon Glass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40547] = { id = 40547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Dalaran, With Love", description = "Jabrul was thinking that he'd like to come up to Dalaran and discuss jewel designs with the masters.\n\nBut Jabrul doesn't know how to get up to it. Jabrul did have an interesting idea that might work.\n\nIf you mailed Jabrul to Dalaran, then surely he'd arrive safe and sound.", progress = "Jabrul is SO anxious!", completion = "That was a much rougher trip than Jabrul thought it would be. But nonetheless, Jabrul is here.\n\nJabrul can't wait to start working with the masters here!", objectives = "Crate up Jabrul and mail him to the Cartier & Co Fine Jewelry shop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40556] = { id = 40556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jabrul Needs You", description = "Hello {name},\n\nJabrul needs your help with something. Could you please come to Azsuna and find Jabrul?\n\nThank you,\n\nJabrul", completion = "{name}, good to you see you again! Now listen...", objectives = "Find Jabrul in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40557] = { id = 40557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Clive Cozen Leave" }
quests[40558] = { id = 40558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Socket to Me", description = "You admire the contraption sitting on the counter. There's a button on it, but pressing it seems to warrant no response.\n\nTiffany tells you that it's an old toy box, but the crystal components are all broken.\n\nIf you were to find new ones, she could repair it and teach you how to make one for yourself.", progress = "You're going to have to travel all over the world for these, I hope you're up to the challenge.", completion = "<Tiffany holds up the box and explains how she fixed it.>\n\nNow if you ever need to make one for yourself, you should have no problem.", objectives = "Obtain all 6 components from around the world. Refer to Tiffany's notebook for reference on where to acquire each piece.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40559] = { id = 40559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Rook Hold: The Raven's Wisdom", description = "{name}, I've been hearing a lot of talk about Black Rook Hold from our friend here, about a room which contains volumes of texts on just about every type of craft there is.\n\nI'm willing to bet there's a book in there on jewelcrafting that could come in handy for us.\n\nGo there and bring me back anything you find. I'll share a sweet new design I came up with you when you return.", progress = "A book, you'll find, is a design for the mind!", completion = "<Timothy thumbs through the pages.>\n\nWhat a rare find, {name}. Excellent work on finding this.\n\nAs promised, here's a new design I've been holding on to.", objectives = "Go to Black Rook Hold and locate a book on jewelcrafting and bring it to Timothy Jones in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40560] = { id = 40560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maw of Souls: Spiriting Away", description = "What I'm about to ask you to do is no easy task, {name}.\n\nI need you to die. But, you'll be able to come back of course! \n\nThere's a ship, the Naglfar, that ferries souls from this world to the next. It's said that an ancient treasure called the Ring of the Fallen rests in the bowels of that ship.\n\nYou know me, {name}, and nothing catches my interest more than a sweet looking ring.\n\nFind a way onto that boat and bring me back that ancient treasure.", progress = "The goddess that rules that world won't let you leave without a fight. Be careful in there, {name}.", completion = "You found it?! And you made it back!\n\n{name}, I came up with a line just for this occasion and just for you.\n\nHe laughs at death, he shrugs off the pain, but {name} comes back again and again!", objectives = "Go to the Maw of Souls and bring back the Ring of the Fallen to Timothy Jones in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40561] = { id = 40561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Valor: Jewel of the Heavens", description = "Queens and kings wear the best rings! And I've heard that a certain king of gods has made his presence available.\n\nIn the Halls of Valor, the ruler Odyn has treasures unlike anyone in existence. If you happen to go there, try and... obtain, let's say, one of his rings for me.\n\nI doubt he'll just hand it over, so you may have the fight of a lifetime in store.", progress = "This will easily be the finest piece in my collection.", completion = "Now that's a ring! How amazing would it be to sit alongside the jewelcrafters of the heavens.\n\nA find as grand as this deserves an equally grand reward. Here's one of my latest ring designs, I hope it servers you well, {name}.", objectives = "Kill Odyn in the Halls of Valor and bring back his ring to Timothy Jones in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40562] = { id = 40562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Personal Touch", description = "{name}, great to see you again. It feels like forever since last we spoke.\n\nWe've received some information about a group of jewelcrafting nightborne in Suramar that are doing fantastic things with necklaces. I'd like to take a look at some of their gems.\n\nAnd their designs.\n\nAnd... a new loupe might be nice, too. I hear the city inspectors carry them.", progress = "Oh, how did I know about the nightborne gems? Well, that's a trade secret.\n\n<Sminx gives you a quick wink.>", completion = "The elves always make the best quality items. I'll hang onto these gems, if you don't mind.\n\nThis jewelry design, on the other hand... it'd be perfect for a jewelcrafting {class} like you!", objectives = "Obtain a Nightborne Loupe, a Custom Jewelry Order, and 5 Nightborne Jewelry Cases.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40564] = { id = 40564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shoe Shine Kit Tracking Quest" }
quests[40565] = { id = 40565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSEME" }
quests[40567] = { id = 40567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkheart Thicket: Enter the Nightmare", description = "We could not save Ysera, but we did prevent her from destroying the temple.\n\nNow I can finally turn my attention to my husband.\n\nI do not know what fate he suffers now. I only know that if we stand any chance of saving him, you must go now.\n\nFollow Xavius into the Nightmare and find Malfurion.\n\nPlease, save my husband if you can.", progress = "Is he alive? Will my husband return to me?", completion = "Praise Elune and all that her light touches... Malfurion is alive.\n\nI thought I would spend the rest of my days alone, dreaming of the choices I did not make.\n\nThank you. Thank you for returning my love to me.", objectives = "Enter Darkheart Thicket and Slay the Shade of Xavius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40568] = { id = 40568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fury of the Storm", description = "The Felskorn who ravage my brood were once Drekirjar - a tribe with whom we shared an ancient pact. Now, under the influence of the God-King, they forsake their oaths and strike at the forebears of their coveted drakes.\n\nThey should answer for this slight.\n\nAwaken your fury, {class}, and take the battle to them!", progress = "Are we rid of the Felskorn threat?", completion = "The Felskorn have witnessed true strength today. \n\nThey will think twice before raising their blades to you again.", objectives = "Kill 10 Felskorn vrykul in Thorim's Peak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40569] = { id = 40569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of the Sands", description = "Nothing! There is next to nothing in our records about this weapon!\n\nI've checked and re-checked, and can find barely a shred of a tale. This can only mean that the story comes from a land outside Pandaria.\n\nLi Li Stormstout is young, but she is the most traveled on the entire isle except for you. If anyone might know of this weapon, it is she.", progress = "What's up?", completion = "Do you think that the story is true? I bet you could control the power of those blades!", objectives = "Speak with Li Li Stormstout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40570] = { id = 40570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into The Heavens", description = "This stone is saturated with elemental power, possibly the remnant of the magic used against Irmaat!\n\nIf you went outside and held the stone aloft, it should unleash the stone's essence as a mighty whirlwind. So potent a windstorm could carry you and your companion all the way to Skywall!\n\nIf the hand blades of Irmaat, the Fists of the Heavens, are as powerful as the old tales say, they would certainly be found there.", completion = "That was a fantastic trip, {name}! We really should do this kind of thing more often!\n\nNow that you have those blades I bet there's going to be a bunch of adventures ahead!\n\nMaybe I should just stick around here a while.", objectives = "Obtain the Fists of the Heavens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40571] = { id = 40571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkheart Thicket Heroic Reward Quest" }
quests[40572] = { id = 40572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkheart Thicket Normal Reward Quest" }
quests[40573] = { id = 40573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nightmare Lord", description = "You arrived just in time, friend.\n\nKagraxxis was moments away from sacrificing me to his master... I was certain I would perish.\n\nI am grateful, but we are not out of danger yet... Xavius has returned.\n\nThe Nightmare Lord is here in Val'sharah, personally orchestrating the corruption of this land. My captor revealed as much to me before I was to be sacrificed.\n\nWe must find Thaon Moonclaw and inform him before it is too late!", completion = "Thaon Moonclaw was a great druid and a true protector of this land.\n\nHow can we hope to defeat the Nightmare Lord without him fighting beside us?", objectives = "Inform Thaon Moonclaw of the return of Xavius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40574] = { id = 40574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Golganneth Shrine Cleansed" }
quests[40578] = { id = 40578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paying Respects", description = "All I see is despair.\n\nLook, {race}. The grounds are overwhelmed with these wraiths, spirits of those interred here. Something has made them angry and they are lashing out. I can feel their pain.\n\nI will go look for remaining relics, and there is a tomb I must see. It is too late for these unfortunate souls. Please defeat any you find and return them to the rest they deserve.", completion = "It pains me to see them suffering. In time they will return, but for now they will be at peace.", objectives = "Slay 8 Disturbed Apparitions or Disturbed Spectres.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40579] = { id = 40579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Legend", description = "As the greatest warrior in these halls, you require a great weapon to do both your will and mine. I have looked down on Azeroth and found artifacts worthy of your hands.\n\nI leave it to you to choose which artifact you wish to seek out and wield against the Legion. We will recover the others in time.", progress = "Choose wisely, {name}.", completion = "I knew you would pick that one. Let us be about it.", objectives = "Select an artifact weapon to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40580] = { id = 40580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protection Chosen" }
quests[40581] = { id = 40581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fury Chosen" }
quests[40582] = { id = 40582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arms Chosen" }
quests[40583] = { id = 40583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making the Cut - Choice UI - Deadly Deep Amber" }
quests[40584] = { id = 40584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Witnessed Drake Lift Crystal" }
quests[40585] = { id = 40585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thus Begins the War", description = "The Legion thinks you are dead. It will be quite the surprise when you punish them for that assumption!\n\nThis allows us to see all across the Broken Isles and assign warriors to various tasks.\n\nOnce you've taken a look, you should choose your first area of operation. I've already picked out the best spots!", completion = "An excellent choice, {name}. As more opportunities arise, I will bring them to your attention. Good luck in battle!", objectives = "Select your order's first assault point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40586] = { id = 40586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making the Cut - Choice UI - Quick Azsunite" }
quests[40587] = { id = 40587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making the Cut - Choice UI - Masterful Queen's Opal" }
quests[40588] = { id = 40588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Following the Curse", description = "Very well. I suppose an introduction is in order. I am Revil Kost, priest of the Light and a seeker of lost artifacts. I've dealt with the Dark Riders before, and have returned to rid this place of them.\n\nThe Riders are elusive, but I may have a clue to their whereabouts. In our previous confrontation, I was able to see a glimpse into their past. Granted blessed vision by the Cloak of Purity, I saw the Dark Riders for who they were before.\n\nCome with me to Ariden's camp. I will explain on the way.", completion = "It's strange that the Dark Riders haven't followed us here, but I will take whatever boon I can get.\n\nI believe the key to finding the Dark Riders is here somewhere. Let us begin our search.", objectives = "Escort Revil Kost from Manor Mistmantle in Duskwood to Ariden's Camp in Deadwind Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40590] = { id = 40590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warrior Inbound", description = "Skylord, the mission to Dalaran was successful. The warrior awaits your return at the Halls of Valor.", objectives = "Use Skyjump to Halls of Valor to return to your order hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40591] = { id = 40591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Second Valarjar", description = "Whatever your feelings towards him, he is still one of the finests warriors on Azeroth. He has led battles from the front, advised Warchiefs, and mixes excellent martial prowess with tactical calm. You can trust his judgment as well as his axe. Speak with him yourself.You will learn:", sourceObjective = "Welcome your new valarjar.", sourceObjectiveStatus = "unverified-source-field" }
quests[40593] = { id = 40593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demons Among Us", description = "The king is wise to focus on the Legion's threat, {name}. Even now, the demons move against us.\n\nThe Illidari will aid the cause of the Alliance. We believe they have set their sights on key locations around Azeroth. In fact, they could already be in your midst!\n\nI sense they are close...", progress = "I never suspected they had infiltrated my own throne room! Praise the Light you were here!", completion = "This attack... even the battle on the Broken Shore... it's only the beginning of the Legion's campaign.\n\nIf we don't find a way to stop them, we're going to lose everything my father and the other leaders built.\n\nWe need the strength of the Illidari behind us.", objectives = "Protect Stormwind Keep from the Legion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40594] = { id = 40594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Justice Rains from Above", description = "Kill now, grieve later!\n\nHere, champion, take flight with one of my war eagles. Use the powers bestowed upon you by our united tribes and help us rain destruction down on these drogbar.\n\nLet us clog that new doorway to their lair with the bodies of their own!", progress = "The drogbar sure do love those rocks.", completion = "Well done. We will make a Skyhorn out of you yet.", objectives = "Bomb the forces of the Understone Breach", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40597] = { id = 40597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunder Totem Treasure" }
quests[40598] = { id = 40598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finishing Touches - Choice UI - Skystone Loop" }
quests[40599] = { id = 40599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finishing Touches - Choice UI - Deep Amber Loop" }
quests[40600] = { id = 40600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finishing Touches - Choice UI - Azsunite Loop" }
quests[40601] = { id = 40601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Vignette - Pinerock Basin - Highmountain Beastmaster See Treasure (JLW)" }
quests[40603] = { id = 40603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking the Valkyra", description = "We simply cannot risk another catastrophe like that; we have to protect the Heart against fel energy before we continue our work.\n\nThe mighty Ashildir has proven willing to aid those who she deems worthy, and her master just may be able to help us protect the Heart.\n\nYou should seek her out at the Vault of Eyir in Stormheim. I'll meet you there.", completion = "Speak not. I know what you seek.\n\nDo you believe yourself ready to face the trials ahead?", objectives = "Seek out Ashildir at the Vault of Eyir in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40604] = { id = 40604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disturbing the Past", description = "This place is where the merchant, Ariden, set up camp while he was trying to ply his dubious wares to the sorcerer Medivh. It has remained strangely untouched for all this time, which leads me to believe it may still have a connection to its former owner.\n\nHelp me search the camp. Let's see if we can find something to lead us to the Dark Riders.", completion = "Otherwise an ordinary looking journal, this book hums with dark energy as you approach it.\n\nA quick scan of the writing reveals this as the journal of Ariden, and chronicles his time in Deadwind Pass. Toward the end of the journal, the writing begins to change, and the tone becomes noticeably darker. It constantly refers to \"the curse\" and of the endless desire to possess things of great power.\n\nOne such entry catches your eye as you glance through.", objectives = "Search around Ariden's Camp for clues leading to the Dark Riders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40605] = { id = 40605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep Your Friends Close", description = "The Legion is bold indeed to strike at the Horde's stronghold! You aided our defense, but now I have a more important task for you.\n\nIt seems the demon hunters will play a crucial part in this war... but I still don't trust them. You will be my envoy to the Illidari. Learn what they know. Study their techniques. If they betray us, we'll use their own knowledge against them.\n\nTheir camp lies atop the plateau in the city. Go. Nathanos and I will clean up this mess.", completion = "Ah, so you're the vaunted {class} I've heard about. Good.\n\nWe shall see if your reputation holds true.", objectives = "Speak to Elthyn Da'rai at the Illidari camp atop the plateau in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40606] = { id = 40606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Point the Way", description = "Though the journal devolves into dark ramblings written in hurried scribbles, one entry stands out:\n\n\"Ulthalesh. The name rings in my head. I can hear it calling, but where?\n\n\"The spirits... the very land here is tied to it. It is no wonder we would so often get lost in this place. The forces pull my compass point in every direction...\n\n\"Perhaps if it had a stronger pull, the compass could show the way...\"", progress = "Is that the one?", completion = "There is definitely something wrong with this compass. \n\nIt seems to be trying to point in all directions at once.", objectives = "Find the compass mentioned in the journal in Ariden's Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40607] = { id = 40607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demons Among Us", description = "Look around. What do you see?\n\n<Allari glares at something over your shoulder.>\n\nThe Legion has already infiltrated the Horde... even now, they are among you.\n\nWe must protect your Warchief.\n\nWhen you are ready to see what lies beneath the veil, say the word.", progress = "The Illidari were right! Destroy the demons, {name}!", completion = "It would seem the demon hunters' concerns were well-founded. To think the demons would dare worm their way into our city during this period of mourning!\n\nThis does not bode well for the rest of my kingdom.", objectives = "Learn what Allari the Souleater sees.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40608] = { id = 40608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mark", description = "Your blade is powerful, but it has not yet met its full potential. The all-powerful Odyn in the Halls of Valor can bestow upon you his strength.\n\nIn order to seek this blessing, you must bring him a worthy tribute. I know where you may obtain such a gift, but in order to retrieve it you must first receive the mark of the Valkyra.\n\nProve yourself worthy of our mark, champion, then you may enter the Vault of Eyir- the goddess will guide you from there.", progress = "Greetings, champion. How go your trials?", completion = "<Ashildir nods knowingly.>\n\nYou are ready for the next step.", objectives = "Prove your worth to the Valarjar, then receive the Mark of the Valkyra from Eyir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40609] = { id = 40609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Vignette - Windripper Peak - Taurson - Tracking Quest Credit - See Treasure (JLW/RKS)" }
quests[40610] = { id = 40610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Vignette - Worm Treasure - Tracking Quest Credit - See Treasure (JLW/RKS)" }
quests[40611] = { id = 40611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Deadwind", description = "The journal mentions a \"stronger pull\" for the compass. If the spirits of this place are indeed tied to it, they may serve as the pull we need.\n\nI've come upon several locations in the pass where restless spirits tend to appear. Perhaps if you show the spirits there the compass, they may be able to help point it in the right direction.\n\nYou seek these locations out. I'll continue on to Karazhan and see if I can find anything leading to the Dark Riders.", completion = "It looks like it worked, and the compass is pointing toward the river. \n\nCould it be..?", objectives = "Attune Ariden's Compass at the sites of restless spirits around Deadwind Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40612] = { id = 40612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Vignette - Amateur Hunters - Tracking Quest Credit - See Treasure (JAP)" }
quests[40613] = { id = 40613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maw of Souls: Retrieving the Svalnguard", description = "The Svalnguard was once Odyn's shield; it is said that it hid the Halls of Valor from the endless darkness below his realm.\n\nHelya, who was cast from the shining halls long ago, stole The Svalnguard and keeps it on her accursed ship, the Naglfar.\n\nYou must board the Naglfar, defeat Helya, and retrieve The Svalnguard - it will make a worthy tribute for Odyn.", progress = "Have you wrested the Svalnguard from Helya's clutches?", completion = "There is one last task before you journey to the Halls, {name}.", objectives = "Retrieve the Svalnguard and defeat Helya in the Maw of Souls on Mythic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40614] = { id = 40614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Feast Fit for Odyn", description = "It is customary in the Halls of Valor to feast after battle is finished. Presenting a truly glorious feast to Odyn from beasts worthy of his throne will show him your determination to earn his blessing.\n\nAcquire flank meat from Thunderhoof in Stormheim, Spinesever's spine in Highmountain, and the finest cut of steak from Leytusk in Azsuna. They will make a feast worthy of the great battle to come.", progress = "The beasts you hunt have taken the lives of many.", completion = "My guards will prepare the feast. We must discuss your journey to the Halls.", objectives = "Acquire flank meat from Thunderhoof in Stormheim, Spinesever's spine in Highmountain, and a steak from Leytusk in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40615] = { id = 40615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Valor: Odyn's Blessing", description = "You are ready, {class}.\n\nTravel to Odyn's shining halls and offer the feast on the altar just inside. Mighty Odyn will then set his gaze upon you - you must pass the ancient trials of the Valarjar under his watch.\n\nOnly then will you receive Odyn's blessing.", progress = "Few have sought Odyn's blessing and returned triumphant.", completion = "I can feel Odyn's power from here - the Legion's magic will no longer stop you.", objectives = "Obtain Odyn's blessing in the Halls of Valor on Mythic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40616] = { id = 40616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - W1 - Saw Leader Die" }
quests[40617] = { id = 40617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turn Around, Nighteyes", description = "Stranger, you must help me!\n\nNighteyes, my old friend... he was scouting ahead and I heard him cry out a warning. I tried to run after him, but in my carelessness I stepped in this trap.\n\nHe's so close, just on the other side of this ridge. Please find him!", progress = "You must find Nighteyes!", completion = "Thank you, {race}. I will tend to Nighteyes' wounds. Tell me what happened!", objectives = "Help Lilryia Dawnwind find Nighteyes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40618] = { id = 40618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Legend", description = "Three weapons... three worthy paths.\n\nAcquiring one such artifact will be the first step in battling the Legion. The weapon will grow in power as you wield it, so you must choose the one which will be the focus of your efforts, {name}.\n\nAfter a time, you will be able to pursue the other weapons. But you must decide which to seek first.", completion = "Now you must begin your pursuit of the artifact. It will not be easy to obtain, but a weapon this powerful seldom is.\n\nAfter you succeed, return here to me and we shall speak at greater length. There is much for us to do!", objectives = "Select your first artifact weapon to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40619] = { id = 40619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survival Chosen" }
quests[40620] = { id = 40620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marksman Chosen" }
quests[40621] = { id = 40621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beast Mastery Chosen" }
quests[40622] = { id = 40622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aman'thul Shrine Cleansed" }
quests[40623] = { id = 40623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Riders", description = "There's a sewer grate along the edge of the river leading to catacombs underneath Karazhan. I've never paid it much attention, but it could be where the spirits are directing us.\n\nTo think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", progress = "Did you find what you seek, {class}?", completion = "Today was a great blow against the Dark Riders, and a victory for the people of Duskwood. \n\nThey are in your debt, as am I.", objectives = "Defeat the Dark Riders in the Karazhan Catacombs and claim Ulthalesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40625] = { id = 40625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Different Source", description = "I need you to fetch me something.\n\nI think I might be on the verge of a breakthrough of a new source of magic, but I require tools. \n\nI can no longer access my workshop, but I have seen the smaller demons below using tools. Bring me one of their tools and I can save our people.", progress = "Did you find anything? I did not exactly get a chance to pack my things before I was exiled.", completion = "This was all you could find? I suppose it will have to do, although it is a primitive instrument.", objectives = "Find a Fel Deconstructor for Kyrtos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40627] = { id = 40627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Odyn Event Complete" }
quests[40628] = { id = 40628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Ashbringer" }
quests[40629] = { id = 40629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiery Ashbringer" }
quests[40630] = { id = 40630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shattered Ashbringer" }
quests[40631] = { id = 40631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basking in Glory", description = "You... you glow with the radiance of Odyn himself...\n\nYou must return to your people at once. Odyn's light is a gift that must be shared with all.", sourceObjective = "Return to Sister Elda in the Sanctum of Light.", sourceObjectiveStatus = "unverified-source-field" }
quests[40632] = { id = 40632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Me To Your Leader", description = "I am glad you are here, {name}.\n\nThis... Khadgar, the archmage who found my message, has called a meeting.\n\nHe wishes to meet us by the entrance to the city as soon as possible.\n\nWill you accompany me? I have the strangest feeling that he will not be alone.", completion = "Hello again, champion. I see we are all here now.", objectives = "Meet with Khadgar in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40633] = { id = 40633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off To Adventure!", description = "Oh I'd love to go see if that story is true! But Pops is too busy stuffing his gut and being a grouch to let me go do any real exploring. He even told me that I can't leave the village unless I have a guardian!\n\nIs Pops for real? I can protect myself just fine!\n\nSay, would you be my guardian? Please, get me away from this boredom and you will totally be my hero!", progress = "Do you see this place? This is so neat!", completion = "Hey there, {name}. What took you so long?\n\nWhile you were traveling the long way I've been doing some research of my own. King Phaoris offered to help us as long as we can take care of a problem for him.\n\nI'm sure you'll be able to handle whatever it is.", objectives = "Meet with Li Li in Ramkahen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40634] = { id = 40634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunder on the Sands", description = "I know the tale of Irmaat well. It is said that his home was the ancient city of Ahmtul, long buried under the desert sands.\n\nRecently a strange storm has appeared over the ruins. What's more, I am told that an elemental called Nader has attacked my people in nearby lands.\n\nThese events must be related.\n\nFind this Nader and put an end to him. Make sure to search his body for clues as to what is behind this.", progress = "Have you found anything, {name}?", completion = "So, you found this stone upon his body?\n\nInteresting... Let me take a closer look.", objectives = "Defeat Nader and search his body for clues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40635] = { id = 40635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sashj'tar Slayer", description = "I cannot believe that Throndyr is gone.\n\nBy the horns on my head, we shall have revenge for all of the pain that the Sashj'tar have inflicted on us!\n\nPress forward, {name}. Kill them! Kill them all!", objectives = "Slay 12 Sashj'tar naga in Azuregale Cove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40636] = { id = 40636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prepare To Strike", description = "The Burning Legion took us by surprise at the Peak of Serenity. We will not allow them to do so again!\n\nWe have trained hard, but we need weapons capable of destroying this great evil if we are to have any chance of success.\n\nOur scrolls speak of several weapons that should prove suitable, but we are unable to decide which one to pursue first.\n\nThe choice, Grand Master, is yours.", completion = "As you wish, Grand Master.", objectives = "Select an artifact weapon to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40637] = { id = 40637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Honor", description = "<Brandolf breathes heavily.>\n\nThis cave will be my final resting place, {name}.\n\nFind Toryl. Tell her of what happened here today.\n\nTell all of Jandvik that I died defending our village...", sourceObjective = "Return to Toryl in Jandvik.", sourceObjectiveStatus = "unverified-source-field" }
quests[40638] = { id = 40638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windwalker Chosen" }
quests[40639] = { id = 40639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistweaver Chosen" }
quests[40640] = { id = 40640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewmaster Chosen" }
quests[40642] = { id = 40642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power! Get The Power!", description = "I need more power. I need more!\n\nI can control the energies, and they are enough to sustain me. For now.\n\nI will not end up withered, like those weaklings.\n\nGo out into Felsoul Hold and slay the demons. Bring me their essence and make it quick!", progress = "Do you have the essence? I must have it!", completion = "<Kyrtos greedily consumes the essence.>\n\nAhh, much better. My senses are focused and ready for research!", objectives = "Collect 8 Fel Essence for Kyrtos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40643] = { id = 40643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Summons From Moonglade", description = "{name}, Your presence is requested at Moonglade at once.\n\nWe are preparing for a ritual of great importance and will require your assistance.\n\nI will meet you there, so please come with haste.", completion = "{name}, I'm pleased you came on such short notice.\n\nWe have a great undertaking here in the Moonglade that is about to begin, one in which you will play a key role.", objectives = "Meet Hamuul Runetotem at the Moonglade.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40644] = { id = 40644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dreamway", description = "The preparations for the ritual are now complete.\n\nCome with me, {name}, I will guide you to the ceremony.", completion = "Well done, {name}!\n\nNow that the path is open we can begin our journey to Val'sharah.", objectives = "Assist with the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40645] = { id = 40645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To The Dreamgrove", description = "The portal to the Dreamway is open and it is here where our paths must part. The Moonglade remains vulnerable to the attacks of the Burning Legion and I must ensure it is well defended.\n\nI'm entrusting you with the mission to Val'sharah, {name}. Archdruid Greathoof is the leader of the druids there. He is wise in the old ways and will provide us invaluable assistance.\n\nThe Dream can be dangerous so I will send Keeper Remulos to guide you. Meet with him upon the other side.", completion = "You did well to navigate through the Emerald Dream to get to this place. Still, there are times when you might wish to return here a bit more quickly. This spell will guide you.\n\nTraveling the Dreamway is no small feat in itself, but it pales to the tasks ahead.", objectives = "Go through the portal to the Dreamgrove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40646] = { id = 40646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Legend", description = "I agree with Keeper Remulos. To confront and defeat the Legion, we will need weapons of legendary power.\n\nAmong the history of our kind, there have been four weapons of renown.\n\nTell me, which weapon would you pursue first?", completion = "Excellent choice, {name}!\n\nWith the power of that weapon in your hands we will be able to bring balance back to Azeroth.", objectives = "Select an artifact weapon to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40647] = { id = 40647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Dreams Become Nightmares", description = "Now that we have Ursol's blessing, we can safely pass the magical wards and reach the claws' resting place!\n\nNow, we must pass into the Dream. Lay down before the Shrine of Ursol and drink of the moonwater you brought earlier and your spirit will drift off into the dream.\n\nBe careful, the Dream can be a dangerous place.", progress = "Have you retrieved the Claws of Ursoc?", completion = "I owe you my life, {name}. If it wasn't for your actions I'd be dead or worse.\n\nThat traitor, Xavius, may have taken Ursoc but at least we were able to recover the claws. Hope is not lost to us yet.", objectives = "Enter the Emerald Dream and obtain the Claws of Ursoc.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40649] = { id = 40649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Mylune", description = "It would seem we are fortuitous that you seek G'Hanir this day, {name} - the dryad Mylune arrived not long ago from the sacred shrine where the staff has been guarded for many centuries.\n\nFew are privy to its hidden location within the roots of Shaladrassil, but you have certainly earned that right.\n\nSpeak to Mylune when you are ready to depart - I saw her last just east of here up the hill.", completion = "<Mylune's eyes are watery with dew, her usual smile an unsightly frown.>\n\nY-yes?", objectives = "Find Mylune.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40650] = { id = 40650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Zen'tabra", objectives = "I ben tinkin' for a while, {name}. I set aside my walking staff a long time ago for a life of peace, seekin' to teach da druidic arts in my twilight years.\n\nBut now, war has come to tear my home to shreds, and I can't watch that happen.\n\nMy staff and I are ready for another journey with you, {name}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40651] = { id = 40651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seed of Ages", description = "These weapons were crafted with ancient magic. The true power of your artifact lies in its ability to grow in strength. The more you use it, the stronger it will become.\n\nNow that you have attuned your weapon to the Seed of Ages you can use its magic to unlock additional attributes in your weapon.\n\nUse it now, and unlock your weapon's potential.", completion = "Excellent!\n\nAs your weapon grows in power you can return here and unleash its true potential.", objectives = "Imbue your weapon with power by assigning an artifact point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40652] = { id = 40652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Word on the Winds", description = "It is time that we turn our attention to matters in the Broken Isles.\n\nSkylord Omnuron has gathered information on events from all over the Isles. If we are presented with any opportunity to strike against the Legion he will know of it.\n\nGo and see if he has anything available.", completion = "Greetings, Archdruid.\n\nThe threats we face are numerous. We must act quickly.", objectives = "Speak to Skylord Omnuron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40653] = { id = 40653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Trails", description = "The Burning Legion threatens the life of Azeroth, but the nightmare threatens its very soul. We must remove both threats if our world is to survive.\n\nThis map will allow us to track the developments all across the Broken Isles and respond to threats as they arise. Our forces are limited for now, so we should focus our efforts where they will be the most effective.\n\nOnce you've taken a look, you should choose where we shall begin.", completion = "Yes, I agree. That is a good place to focus our initial efforts.\n\nAs new threats arise, I will bring them to your attention. Elune guide your path, Archdruid.", objectives = "Select your order's first operational area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40654] = { id = 40654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druids of the Claw", description = "A new ally has joined our ranks. His name is Yaris Darkclaw, a skilled trainer among the Druids of the Claw.\n\nGo speak to him now.", completion = "Excellent. Soon enough, the Druids of the Claw will bolster our ranks.", objectives = "Speak to Yaris Darkclaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40655] = { id = 40655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Li Li" }
quests[40657] = { id = 40657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Road to Fel", description = "An early step to understanding how magic works is to understand and study materials made using that magic. That was how I made my breakthrough on warlock soul crystals, after all. \n\nThe wyrmtongue minions in this pit hammer plates into their structures for support and maintenance. Those will be a good starting point. Fetch me some, my faithful assistant!", progress = "I can practically feel the buildings hum with power.", completion = "Excellent. By studying these materials I can better understand how they imbue magic into their machinery and architecture.", objectives = "Gather 10 Fel-Infused Plates for Kyrtos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40658] = { id = 40658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - W1 - See Demon Attack" }
quests[40659] = { id = 40659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeing Stars", description = "You think those naga are good sport, little rabbit?\n\n<Stokalfr chuckles.>\n\nI would savor the chance to do battle with one of those barnacle-crusted behemoths.\n\nIf you want to impress me, bring me the stars from their heads. I might consider you a true {class} then.", objectives = "Collect 4 Sea Stars from Elder Trenchwalkers in Azuregale Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40661] = { id = 40661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protect the Home Front", description = "The Legion hasn't just invaded this city. Their evil is spreading across Azeroth, threatening the far corners of our world.\n\nWe must seek them out and stop them, everywhere their darkness touches.\n\nWe've dispatched scouts around the world to watch for Legion activity. As invasions arise, we'll mark the locations on your map.\n\nMake them suffer, {name}!", progress = "Find them! Stop them! Suffer well!", completion = "You've done it! You've broken an invasion!\n\nIf only that had ended our campaign. But the Legion will never relent until they are destroyed... or have destroyed us.\n\nDon't let up! Fight off more of these wretched invasions, {name}. The wyrmtongue we're holding captive here will reward your efforts.", objectives = "Open your map to find an active Legion invasion in Kalimdor or Eastern Kingdoms. Go to the invasion site and stop the demons!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40662] = { id = 40662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shattered Chosen" }
quests[40663] = { id = 40663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiery Chosen" }
quests[40664] = { id = 40664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Chosen" }
quests[40668] = { id = 40668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye of Azshara: The Heart of Zin-Azshari", description = "The naga in the Eye of Azshara summon terrible storms that ravage the coastline of Azsuna - storms far beyond the abilities of even their best sirens.\n\nIt can only be the Heart of Zin-Azshari.\n\nPrior to the Sundering, Azshara's chosen used the Heart to greatly magnify their power - it is said to have been key in their dominance of the Well of Eternity.\n\nIf you can journey to their domain and retrieve it, {name}, we will put its power to far better use than those foul creatures.", progress = "Have you retrieved the Heart?", completion = "The Heart will require a great deal of work to properly hone the destructive energies within its depths, but I have faith that you will prevail.", objectives = "Retrieve the Heart of Zin-Azshari and defeat the Wrath of Azshara in the Eye of Azshara on Mythic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40672] = { id = 40672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharion's Lair: Presentation is Key", description = "Odyn will demand a feast worthy of the ancient trials you must complete; a feast's merit begins not at the great beasts piled upon it, but at the dish used to serve it.\n\nDeep beneath Highmountain lies the former lair of Neltharion - you may know the infernal drake better as Deathwing. You will find remnants of the adamantium plating used to hold his molten skin together in the deepest recesses of his lair.\n\nThey will form a fine dish for the feast.", progress = "Dare not serve Odyn a feast upon an improper dish. Such action will only earn his ire.", completion = "These will make a worthy vessel indeed.", objectives = "Retrieve 4 Adamantium Casing Scraps and defeat Dargrul the Underking in Neltharion's Lair on Mythic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40673] = { id = 40673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Knowledge", description = "We are indeed familiar with the Nightborne's magic, but we were never allowed access to the Heart. It was a right reserved only for the Queen's favored.\n\nHowever, we can still learn how to properly tap its magic.\n\nThousands of years ago, a Nightborne scholar studied the Heart and documented his findings in great detail. He was executed and the scroll of his writings banned, but the Nightfallen secreted it away in their escape.\n\nIf you obtain the scroll, we can help you.", progress = "The Nightfallen have become... distrustful... since the Nightborne's betrayal. You will have to earn their respect before they will let you near the scroll.", completion = "<Thalrenus reads over the scroll carefully.>", objectives = "Obtain the Scroll of Elun'dris from First Arcanist Thalyssra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40674] = { id = 40674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jars for Jandvik", description = "Last time we met, {race}, I was in a cage. You risked your life once before for my kin. Are you willing to aid me once again?\n\nThe serpents' attack has left many of us wounded. I require mending waters to perform my healing rituals.\n\nI have seen the serpents use this water. Return any that you find to me.", objectives = "Retrieve 6 Mending Water from the Sashj'tar Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40675] = { id = 40675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arcway: Rite of the Captain", description = "Only a captain of the Guard may receive the power of our order - our ancient laws forbid otherwise.\n\nYou must complete the rite of the captain.\n\nTraditionally, aspirants patrol the Arcway for three weeks without rest, the vast labyrinth putting their skills as a Guard to the test. Our laws must still be honored, but I believe there another way you may prove yourself.\n\nElisandre's advisor, Vandros, has recently descended into the Arcway's depths. Kill him, and take his Eon Winder.", progress = "Have you completed the rites as asked?", completion = "Well done. The Eon Winder will help us control the delicate magics at play within the Heart.", objectives = "Take Advisor Vandros' Eon Winder from The Arcway on Mythic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40676] = { id = 40676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Must Make Haste", description = "I suggest that you set off immediately, {name}. You have been here for far too long - the Legion's assassins could close in at any moment to make an attempt on your life.\n\nDo take caution when using the heart - even with the bindings to aid you the power within is dangerous.", sourceObjective = "Return to King Magni Bronzebeard in the hills below Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[40678] = { id = 40678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twisted Power", description = "It is time we put our work to the test by infusing the most potent source of power I know of - fel magic.\n\nRarely, the Legion's minions will carry fragments of the greater portal stones used to usher in their eredar masters. If you gather enough to form a complete stone, you can use it in Faronaar to call forth the eredar lord Vizuul the Twisted at the Altar of End Times.\n\nThe bindings Vizuul wears to augment his power should push the Heart to its very limit.", progress = "Do you have the bindings?", completion = "Now, let's see what happens if we use the Heart to drain the power from them.", objectives = "Use a Greater Portal Stone to summon Vizuul the Twisted at the Altar of End Times in Faronaar and collect his runebindings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40680] = { id = 40680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar - Vignette: Rok'nash - twh" }
quests[40681] = { id = 40681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snarf" }
quests[40683] = { id = 40683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discovery Requires Experimentation", description = "I can sense residues of magic all over you. You will be useful.\n\nI must study how the demon bodies can handle the fel energies in such large quantities. I have plenty of flesh to sample, but there must be something...\n\nGo retrieve some spines from the nearby basilisks so that I may analyze their magical residues. No sense in both of us getting our hands dirty, is there?", progress = "I hope you brought enough. I will require more energy before my studies are complete.", completion = "Fel magic is... strange. Almost slippery like an oil, and it burns long and hot. Maybe there's a connection...", objectives = "Collect 8 Felfire Spines from Felfire Basilisks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40684] = { id = 40684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Blighted Implements", description = "The book you carry is the key to your friends' salvation, and to your absolute power! It holds within information about many relics too dangerous to the Legion to leave unchecked.\n\nRead, friend. And decide which of these artifacts you will use to strike Jagganoth down!", progress = "Have you made your choice?", completion = "Yes, friend chose very wisely!", objectives = "Speak with Calydus to choose which artifact you will pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40685] = { id = 40685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Mouth of the Nether", description = "With the ritual failed and the council scattered, you find yourself trapped in the prison of the pit lord, Jagganoth.\n\nThe situation is grim, but with the help of the remaining council members, you may be able to escape.", objectives = "Escape from Dreadscar Rift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40686] = { id = 40686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Affliction Chosen" }
