quests[40689] = { id = 40689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reward: Deadwind Harvester" }
quests[40690] = { id = 40690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reward: Staff of Sargeras" }
quests[40691] = { id = 40691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reward: Skull of the Man'ari" }
quests[40692] = { id = 40692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar - Treasure 000 - The Drift - L (DLA)" }
quests[40693] = { id = 40693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of Nashal - Choice UI - Deadly Eye of Prophecy" }
quests[40694] = { id = 40694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Small Step for Magic", description = "It is time to embrace the future.\n\nI have mastered every magic known to our kind. I will master this one.\n\nBy applying the principles of arcane magic it is fairly trivial to control the primitive fel energies within the material you have given me. I need to move to live prey next.\n\nLet us start with a small summoning. Defeat the creature for me and watch how a true scholar works!", progress = "Ahh, this is a most interesting observation.", completion = "Yes...\n\nThis power is... different. Brutal, blunt, powerful.\n\nI can control it. I can master it!", objectives = "Speak to Kyrtos and assist him with his ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40695] = { id = 40695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of Nashal - Choice UI - Quick Dawnlight" }
quests[40696] = { id = 40696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of Nashal - Choice UI - Masterful Shadowruby" }
quests[40698] = { id = 40698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purity of Form", description = "Master, we have discovered a new technique that allows one with great focus to shape Chi within magical objects. This technique should allow you to considerably improve the abilities of your new weapon.\n\nThis technique requires a great deal of focus so we are limited to only a single upgrade for now, but that will have to do.", completion = "This weapon is truly amazing, yet much of its potential remains untapped.\n\nIf we are to end the threat of the Burning Legion once and for all we will need to fully unlock its power.", objectives = "Use the Forge of the Roaring Mountain to imbue your artifact with a new power.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40699] = { id = 40699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Credit - Scenario Complete" }
quests[40700] = { id = 40700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xalethar", description = "The satyr known as Xalethar has been sighted near the Den of Dreams in Val'sharah.\n\nSeveral reports have come in regarding demon activity in that area. I want you to go and investigate.\n\nSearch for Xalethar near the Den of Dreams and slay him without mercy.", objectives = "Track and slay Xalethar in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40701] = { id = 40701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feral Chosen" }
quests[40702] = { id = 40702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guardian Chosen" }
quests[40703] = { id = 40703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoration Chosen" }
quests[40704] = { id = 40704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Li Li Stormstout", objectives = "You know, I've been thinking about all the fun we've had together. You're great to hang around and I'm sure Uncle Chen wouldn't mind if I stuck around since you're a Grandmaster and all.\n\nWhat I'm trying to say is, I'd be happy to be your explorer, scout, or resident adventurer. So, what do you say?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40705] = { id = 40705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priestly Matters", description = "<Master/Mistress> {name}, I come at the behest of one who seeks to organize a stronger resistance to the Legion threat.\n\nIf you would meet him at Faol's Rest in Tirisfal Glades, he will guarantee both your safety and an opportunity to play a pivotal role in the conflict.", completion = "Can I take that as a yes?\n\nIf you are ready, I'd like to get started immediately.\n\nI know you are immensely capable, but let's not leave anything to chance!", objectives = "Attend the secret meeting at Faol's Rest in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40706] = { id = 40706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Legend You Can Hold", description = "To face the trials ahead, you require a weapon that can enhance your considerable abilities. I have learned of a few possibilities that you might consider.\n\nYou must decide which weapon to pursue first. I have the utmost confidence in your decision.", completion = "A wise choice. My brethren and I stand ready to assist you on your next move, {name}.", objectives = "Select an artifact weapon to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40707] = { id = 40707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Chosen" }
quests[40708] = { id = 40708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holy Chosen" }
quests[40709] = { id = 40709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discipline Chosen" }
quests[40710] = { id = 40710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blade in Twilight", description = "I have been working with Moira Thaurissan to infiltrate the Twilight's Hammer cult. We've learned of an ancient and powerful Old God relic, a blade used at various points in history to wreak havoc.\n\nMoira's double agent informs us a new leader is rising, and plans to cement his ascension using this weapon in an unholy ritual. You must find him, stop the ritual, and seize the artifact.\n\nWe will meet in Dalaran afterwards.", progress = "Not too difficult a task, I hope!", completion = "You have demonstrated no small amount of skill in these sorts of tasks.\n\nThat is good, for we will require even more of you if we are to survive this conflict.", objectives = "Stop the ritual and acquire Xal'atath, Blade of the Black Empire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40711] = { id = 40711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 019 - [Ley Line Tower]" }
quests[40712] = { id = 40712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power Possessed", description = "I was wrong about you, warlock. Your assistance against the Dark Riders has proven a great service to the Light. Perhaps I should not be so quick to judge.\n\nNevertheless, you have allowed me to fill my purpose in returning these artifacts to their rightful owners. As for Ulthalesh, I can think of no safer place than in your care. \n\nMay it serve you well against the Legion, warlock.", completion = "Friend has the weapon? \n\nYes, Calydus can feel its power!", objectives = "Return to Calydus in The Underbelly in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40713] = { id = 40713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Tome", description = "I have made a great discovery, {name}.\n\nThere is a powerful warlock in the Soul Engine, in possession of a powerful tome. It contains forbidden secrets to summoning the most powerful of demons.\n\nEven the Legion is afraid to call on these fel lords, but now I possess knowledge beyond theirs.\n\nFetch me the tome and I will never want for magic again.", progress = "The tome! Do you have it?", completion = "Yes... Within these pages lies the secret to true mastery of this power.", objectives = "Obtain the Black Tome.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40714] = { id = 40714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call To War", description = "<A chilling thought brushes your mind.>\n\nHear me, {name}.\n\nThe Legion has returned. They hope to control us, to bend us to their will. Fools - they only walk back within reach of our blades.\n\nYour brethren within Dalaran have begun to gather at Krasus' Landing. Go, meet with Duke Lankral and all will be explained.", completion = "I'm sure you have many questions, but they're just going to have to wait. We're at war now!\n\nWe have to move quickly, but I'll try to explain what I can.", objectives = "Meet with Duke Lankral at Krasus' Landing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40715] = { id = 40715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pact of Necessity", description = "We have an unexpected ally in this war, {name}, and we're going to need every advantage we can get to defeat the Burning Legion.\n\nThe Ebon Blade will serve as the Lich King's arm as long as the Scourge is confined to Northrend. In return for our assistance, our ally has offered to assist in obtaining powerful weapons for the strongest of our knights. Weapons powerful enough to end the Legion once and for all!\n\nYou are one of our best, {name}. I want you to decide which weapon you would like to seek out.", completion = "Excellent choice.", objectives = "Select an artifact weapon to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40716] = { id = 40716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sixth", description = "Greetings, warlock. I speak on behalf of the Council of the Black Harvest.\n\nWith the Legion invasion upon us, it is painfully clear that our only hope is to grow stronger. The council plans to tap into the Twisting Nether and call forth more powerful demon allies. The ritual is ready, but we are short one number.\n\nNo doubt you have heard of the fate that befell Kanrethad Ebonlocke.\n\nYou will be his replacement. Do you accept?", completion = "You have made the right decision.\n\nLet us hope you live up to your reputation.", objectives = "Meet with Ritssyn Flamescowl in the Circle of Wills beneath Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40717] = { id = 40717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calling of the Council", description = "<The arcane anomaly turns to address you, speaking in what is clearly Khadgar's voice.>\n\nThough I am loathe to interrupt your fight against the Legion, I must request your help in a matter of... diplomacy. We face a grave threat, and we must be at our full strength to overcome it.\n\nSome will not agree with this position.\n\nPlease join me outside the Violet Citadel in Dalaran. We have repositioned the city to defend the Eastern Kingdoms. You'll find it over Deadwind Pass, above Karazhan.", completion = "Jaina's reaction was unfortunate, but not unexpected. She has endured so much...\n\nThough it was Garrosh Hellscream who ordered the obliteration of Theramore, she blames all the Horde for her loss. I hope one day she can overcome that hatred.\n\nEnough ruminating. We must prepare the Kirin Tor for war.", objectives = "Meet Khadgar in Dalaran at its new location above Deadwind Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40718] = { id = 40718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calling of the Council", description = "<The arcane anomaly addresses you in Khadgar's voice.>\n\nThough I am loathe to interrupt your fight against the Legion, I must request your help in a matter of... diplomacy. We face a grave threat, and we require the full might of Azeroth's people to overcome it.\n\nThe Horde must become part of the Kirin Tor once again. Some will not agree with this position.\n\nPlease join me outside the Violet Citadel in Dalaran. We have repositioned the city to defend the Eastern Kingdoms, above Karazhan.", completion = "Jaina's reaction was unfortunate, but not unexpected. She has endured so much...\n\nThough it was Garrosh Hellscream who ordered the obliteration of Theramore, the only thing she can think of when she looks at you, or any Horde, is her desire for vengeance. I hope one day she can overcome that hatred.\n\nEnough ruminating. We must prepare the Kirin Tor for war.", objectives = "Meet Khadgar in Dalaran at its new location above Deadwind Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40719] = { id = 40719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DEPRECATE- REUSE" }
