quests[40723] = { id = 40723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost Chosen" }
quests[40724] = { id = 40724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unholy Chosen" }
quests[40725] = { id = 40725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arganax", description = "A satyr known as Arganax has infiltrated the village of Lorlathil in Val'sharah. I believe that Arganax has disguised himself as one of the local residents.\n\nUse the demon Eye of Azzorok on the villagers in Lorlathil. If there is a demon disguised as a local, the Eye of Azzorok will reveal their true identity.\n\nUncover the demon infiltrator Arganax, and slay him without mercy.", objectives = "Find and slay Arganax in Lorlathil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40727] = { id = 40727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Along the Waterways", description = "I've noticed some wandering eyes, lately.\n\nI am more than happy to continue delivering the goods to Vanthir, but it is getting increasingly dangerous to do so. \n\nThe Duskwatch that walk the bazaar are by far the most observant.\n\nFind and slay the Orbitists so that I may deliver the goods safely.\n\nI will follow behind with the shipment.", progress = "What of Deline?", completion = "Deline was able to deliver the goods safely, thanks to you.", objectives = "Slay 3 Duskwatch Orbitists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40728] = { id = 40728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wormgut's Quest" }
quests[40729] = { id = 40729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Blood", description = "It is time to begin the ritual, warlock. Be prepared, for the summoning we perform today will be more challenging than any you have known or seen before.\n\nAre you ready?", completion = "Calydus sorry we not save your friends, but maybe they survive if we hurry.\n\nJagganoth torture them, yes, but he likes to keep victims alive... mostly.", objectives = "Complete the summoning ritual with the Council of the Black Harvest in the Circle of Wills in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40730] = { id = 40730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redistribution", description = "I would imagine you thought I would simply have wine to deliver.\n\n<Deline chuckles.>\n\nIf it were that easy, his people would not be starving.\n\n<Her expression becomes serious.>\n\nThese... loyalists, shall we say, enjoy abundance. They dance to the Magistrix's whims and so they have all that they need.\n\nThere is no Arcwine shortage. The Magistrix created one to keep us in line.\n\nThey will not miss a few bottles. They have plenty.\n\nSearch the square and bring as much as you can carry back.", progress = "Did you find enough?", completion = "I will see that this gets back to our friend safely. Good work.", objectives = "Acquire 20 Bottles of Arcwine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40731] = { id = 40731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Dreadscar", description = "Friend has the artifact! Now Jagganoth does not stand a chance!\n\nQuickly, you must go back to Dreadscar Rift! You may still be able to save your friends from Jagganoth's vengeance.\n\nIf you take the heart of the overlord, his army will be yours to command!", completion = "The cruel Jagganoth is defeated!\n\nFriend is the new Overlord of the Dreadscar! \n\nThis place will be friend's new home. With the Dreadscar under your control, you can come and go as you please!", objectives = "Defeat Jagganoth and take his heart to the Seat of the Overlord in Dreadscar Rift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40732] = { id = 40732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Reaves Repair Module" }
quests[40733] = { id = 40733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Reaves Failure Detection Module" }
quests[40734] = { id = 40734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Reaves Fireworks Module" }
quests[40735] = { id = 40735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Reaves Snack Distribution Module" }
quests[40736] = { id = 40736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Reaves Bling Module" }
quests[40737] = { id = 40737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Reaves Piloted Combat Module" }
quests[40738] = { id = 40738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Reaves Wormhole Generator Module" }
quests[40739] = { id = 40739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Reaves Thermal Anvil Module" }
quests[40740] = { id = 40740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dead and the Damned", description = "<A powerful mind again touches your thoughts.>\n\nGorelix the Fleshripper is a monstrous demon. The butcher of a thousand worlds, he has exterminated countless races with his axe, the Maw of the Damned.\n\nA group of Ebon Blade was dispatched to slay him but they have gone missing. You will succeed where they failed.\n\nYou will not be alone in this, I've sent Baron Sliver ahead to assist you.\n\nGo, obtain the Maw of the Damned and ensure that Gorelix is no more.", progress = "It is time to begin, {name}.", completion = "That axe makes me feel uneasy, {name}. Its power is undeniable, but its very essence embodies the eternal hunger.\n\nWe will use it because we must do whatever it takes to win this war. Still, I'd be careful with that weapon if I were you.", objectives = "Travel to Dalaran and fly upon Zeomus to Darkstone Isle. While there, travel through the Demon Portal, find Baron Sliver, and obtain the Maw of the Damned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40743] = { id = 40743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 DH-Mardum - Small Treasure Chest 011" }
quests[40744] = { id = 40744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ancient Recipe", description = "Suramar is... was... an intellectual's dream.\n\nWe studied everything in there, from alchemy and the arts to the very nature of magic itself. How could we be so foolish as to accept them in?\n\nLook at me, lost in the clouds again when there is much to be done. My work requires some fairly difficult ingredients, {race}. Perhaps you would help me procure them?\n\nI am going to need some harpy talons. Crushed into a powder, they will be a potent reagent.", progress = "Do you have what I require, {race}? We don't have much time to spare.", completion = "That should be plenty. Talondust loses its potency fairly quickly, so we must make haste.", objectives = "Collect 6 Harpy Talons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40745] = { id = 40745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shift Change", description = "This is as good a chance as we are going to get to rescue Verene's daughter.\n\nHere is how this is going to work. \n\nYou are going to wait here for the guard to pass by on their way to their guard shift. Look for something to hide in.\n\n<Silgryn marks a spot on your map.>\n\nYou will know the guard by their bright red armor.\n\nFollow closely, but not so closely that you are seen. It may be necessary to kill the guard when you reach your destination.\n\nThe child's name is Korine. Good luck.", progress = "W-who are you?", completion = "I-I thought... they were gonna... *sniff*", objectives = "Hide in the basket and wait for the guard to appear. Follow the guard to their destination.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40746] = { id = 40746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One of the People", description = "It is time for you to enter the city proper, {name}.\n\nI am sending you to my loyal friend Vanthir. I do hope you remember him- I can guarantee that he remembers you.\n\nI will not be able to accompany you, but I must stress that the disguise I have granted you is not impervious. Tread carefully, and avoid those who stare too long.\n\nFarewell for now.", completion = "Glad you could make it. Your help is sorely needed here.", objectives = "Meet with Vanthir in Suramar City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40747] = { id = 40747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Delicate Art of Telemancy", description = "I hadn't the time to gather my instruments before fleeing the palace. I came here to salvage some equipment.\n\nThis old workshop is actually several rooms connected by teleporter pads.\n\nElisande's goons are already scouring the place looking for me, but from here I can alter the teleporter network and keep them moving in circles.\n\nYou go in. I'll monitor your position and ensure the teleporters work normally for you.\n\nFind these two parts and bring them back!", progress = "Salvaging the equipment here is necessary if I am to develop a teleporter network for Thalyssra.", completion = "These are in rough shape, but they will suffice.", objectives = "Collect the Weathered Telemancy Beacon and Cracked Warpsleeve from Oculeth's Workshop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40748] = { id = 40748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Network Security", description = "We must lock down the facility. Otherwise my esteemed colleagues from the palace could uncover my secrets, which puts any teleporters I build for you and Thalyssra at risk.\n\n<The inactive attunement device near Oculeth hums to life.>\n\nThis will take us to my secret test chamber beneath the mountain. From there we can begin the lockdown sequence and make our escape!", completion = "Did we... make it?", objectives = "Complete the lockdown sequence in Oculeth's Test Chamber.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40749] = { id = 40749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Token of Remembrance", description = "The flower rests peacefully in your hand, glowing softly.\n\nWhile it doesn't appear to be growing anywhere nearby, there are small bouquets of the flower on some of the memorials around here.\n\nPerhaps laying down some flowers on the remaining graves will ease the gloom.", objectives = "Place 4 Bouquets of Moon Lilies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40751] = { id = 40751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 020 - Olivian Rise" }
quests[40752] = { id = 40752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 021 - Oracle" }
quests[40753] = { id = 40753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blingtron 6000", sourceObjective = "While I am programmed for gift distribution, my observations indicate that you are programmed for gift reception.\n\nShall we engage in a mutually-favorable transaction?", sourceObjectiveStatus = "unverified-source-field" }
quests[40755] = { id = 40755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hiding in the Stacks", description = "Magni's information was enlightening. It should prove handy to have a friend who has the ear of a titan.\n\nIt's time to head into Karazhan. Not that I need to remind you, but it can be a dangerous place. There are countless strata of spells woven throughout the tower, and the interactions of the forces within can be... unpredictable. Be on your guard.\n\nI'll join you inside. I need a moment to... gather my thoughts. This place holds a lot of memories for me.", progress = "Do you have something for me?", completion = "Not long after you left, the first wave of demons struck. We're holding them at bay... for now.\n\nI'll keep this tome safe until we have a chance to study it.\n\nGood work in there. I should like to delve into the libraries of Karazhan myself one day. At least... I think I would.", objectives = "Enter Karazhan and search for knowledge of the Pillars of Creation with Khadgar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40759] = { id = 40759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 DH-Mardum - Small Treasure Chest 012" }
quests[40760] = { id = 40760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emissary", description = "As if things weren't unsettled enough, guests have arrived... the Illidari.\n\nThese demon hunters have been imprisoned since their master's fall at the Black Temple. For the Wardens to release them can only mean the peril is dire indeed.\n\nTheir delegation's leader, Allari \"the Souleater,\" claims Orgimmar faces a hidden threat. I gave them leave to establish a camp within the city... for now.\n\nYou will speak with her at once. Find out whether this threat is credible.", completion = "<Allari furrows her brow as she speaks.>\n\nYou didn't think the leadership of the Horde could gather in one location and go unnoticed by the Burning Legion, did you?", objectives = "Speak with Allari the Souleater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40761] = { id = 40761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers from Oronaar", description = "Ethereals, the Void, a Dark Naaru... I feel they are all connected.\n\nI explored the ruins below while you and Velen were seeking the Crown. There are survivors, {name}.\n\nBroken wander the cluster of buildings to our west- I cannot understand much of what they say but I suspect that their minds are not their own.\n\nIf the Void is to blame, we will need to start our investigation there.\n\nI will conduct my own search in the meantime.", completion = "Something is very wrong here.", objectives = "Investigate the Ruins of Oronaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40762] = { id = 40762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zealot's Dues", description = "Commander Domitille represents the very essence of the Nightborne's corruption. Abhorrent of power not their own, enamoured with their Grand Magistrix to the point of zealotry, and focused utterly on the destruction of the Moon Guard.\n\nTake her helm to Lothrius as proof of her demise.", completion = "I was wondering why she had suddenly gone silent. It is a small comfort to my heart, but a great blow to the remaining forces of the Nightborne. Well done, {name}.", objectives = "Take Commander Domitille's Helm to Lothrius Mooncaller.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[40763] = { id = 40763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Casual Redistribution", description = "Lately there have been a disturbing array of changes involving our most precious resource, Arcwine. \n\nI imagine Thalyssra has thoroughly educated you about what happens when a Nightborne does not have access to a source of power like Arcwine.\n\nWith the presence of the demons came rationing. There are many who do not have enough to sustain themselves.\n\nBring me as much Arcwine as you can carry. I will see that it gets to the right people.", objectives = "Collect 20 Bottles of Arcwine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
